{
    return iVolume(SMC_SYMBOL, PERIOD_CURRENT);
}

//--- Funções de ordem ---------------------------------------------------
bool OpenLong(string sym, string type, int qty, double price, double sl, double tp)
{
    int ticket = OrderSend(SMC_SYMBOL, type, qty, price, 3, sl, tp, "SMC EA Long", 0, 0, clrGreen);
