        // Gravar o início do tempo para esse personagem
        startTime = Time.time();   // ou clock.tick() + frameCount
        isPausedByOther = true;
    }
    else
    {
        // Se não estiver em super pause, limpar o marcador
        if (isPausedByOther)
        {
            ApplyAbility(startTime); // executa habilidade no tempo gravado
            isPausedByOther = false;
        }
    }

    // 3. Lógica normal do personagem (movimento, etc.)
}
